select cr_task_submit.*,cr_task.mission_id mission_hash
,cr_task.user_id submit_user
from cr_task_submit,cr_task

    cr_task_submit.task_id=cr_task.resource_id
    and cr_task.room_id = #{listQuery.roomId}

        and cr_task.user_id = #{listQuery.studentHash}




            and cr_task_submit.score is not null and cr_task_submit.evaluator_id is null


            and cr_task_submit.evaluator_id is not null




        and cr_task_submit.evaluate_status = #{listQuery.evaluateStatus}

select cr_task_submit.*, cr_task.mission_id mission_hash
,cr_task.user_id submit_user,cr_role.`name` submit_user_role,cr_task.role_id submit_user_role_id
from cr_task_submit,cr_task,cr_role

    cr_task_submit.task_id=cr_task.resource_id and cr_task.role_id=cr_role.resource_id
    and cr_task.room_id = #{listQuery.roomId}

        and cr_task.user_id = #{listQuery.studentHash}



        and cr_task_submit.evaluate_status = #{listQuery.evaluateStatus}

select cr_task_submit.*
from cr_task_submit, cr_task
where cr_task_submit.task_id = cr_task.resource_id
and cr_task.room_id = #{roomId}
and cr_task.user_id in

    #{userId}

select cr_task_submit.resource_id, cr_task_submit.evaluate_time, cr_task_submit.create_time as submit_time, cr_task.user_id as submit_user, cr_task.role_id, cr_role.name as role_name, cr_role.role_group, cr_mission.title as mission_title, cr_task_submit.evaluate_status, if(length(evaluator_id)>0, 1, 0) as evaluate_type, cr_task_submit.score from cr_task_submit left join cr_task on cr_task_submit.task_id = cr_task.resource_id left join cr_mission on cr_task.mission_id = cr_mission.resource_id left join cr_role on cr_task.role_id = cr_role.resource_id where cr_task_submit.room_id = #{roomId}
and cr_task.role_id = #{roleId}
and cr_task.user_id = #{userId}
and cr_task_submit.evaluate_status = #{evaluateStatus}
